def _case(passage, stem, right, wrong, evidence, steps, *, difficulty='medium', demands=(), table=None, topic='original hypothetical account'):
    return dict(passage=passage, stem=stem, right=right, wrong=wrong,
                evidence=evidence, steps=steps, difficulty=difficulty,
                demands=demands, table=table, topic=topic)


